const D = { energy: .62, scale: 1, density: .55, speed: 1, depth: .5, gamma: 1.9, persist: .6, hue: 220, x: .5, y: .5, style: 'nebula', act: 'breathe', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- coarse density grid (long axis 190; keyed on canvas aspect) ----
const LA = 190;
let cw, ch;
if (width >= height){ cw = LA; ch = Math.max(64, Math.round(LA*height/width)); }
else { ch = LA; cw = Math.max(64, Math.round(LA*width/height)); }
if (S.gridKey !== cw+'x'+ch){
  S.gridKey = cw+'x'+ch; S.cw=cw; S.ch=ch;
  S.hist = new Float32Array(cw*ch);
  S.csum = new Float32Array(cw*ch);
  if (S.buf) S.buf.remove();
  S.buf = createGraphics(cw,ch); S.buf.pixelDensity(1);
}
cw=S.cw; ch=S.ch; const N4=cw*ch;

// ---- seeded RNG (free-runs; reseed only on P.seed change) ----
if (S.seedUsed !== P.seed){
  S.seedUsed = P.seed;
  let z=(P.seed*2654435761 ^ 0x9e3779b9)>>>0;
  S.rnd=()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  S.hoff = S.rnd()*30-15;   // per-seed hue jitter
}
const rnd=S.rnd;

// ---- palette LUT (256 rgb) built ONCE per style/hue/seed change ----
function hsv(h,s,v){ h=((h%360)+360)%360/60; const c=v*s, x=c*(1-Math.abs(h%2-1)), m=v-c; let r,g,b;
  if(h<1){r=c;g=x;b=0;}else if(h<2){r=x;g=c;b=0;}else if(h<3){r=0;g=c;b=x;}else if(h<4){r=0;g=x;b=c;}else if(h<5){r=x;g=0;b=c;}else{r=c;g=0;b=x;}
  return [r+m,g+m,b+m]; }
if (S.palKey !== P.style+'|'+Math.round(P.hue)+'|'+P.seed){
  S.palKey = P.style+'|'+Math.round(P.hue)+'|'+P.seed;
  const st=P.style, hd=(P.hue-220)+S.hoff, TAU=6.28318;
  S.pal=new Float32Array(256*3);
  let stops=null;
  if (st==='nebula') stops=[[0,230,85,6],[.22,226,92,24],[.46,205,90,58],[.66,188,74,84],[.83,45,84,99],[1,48,10,100]];
  else if (st==='ember') stops=[[0,8,90,5],[.26,6,96,32],[.5,16,95,74],[.72,32,90,100],[.88,48,70,100],[1,50,8,100]];
  else if (st==='ghost') stops=[[0,265,70,7],[.3,270,72,34],[.56,275,58,62],[.78,278,32,86],[1,285,6,100]];
  else stops=[[0,220,25,5],[.5,214,9,44],[1,210,4,100]]; // bone (mono)
  for (let i=0;i<256;i++){ const t=i/255; let r,g,b;
    if (st==='spectral'){ const h0=(P.hue+S.hoff)/360; r=.5+.5*Math.cos(TAU*(h0+t+0)); g=.5+.5*Math.cos(TAU*(h0+t+.33)); b=.5+.5*Math.cos(TAU*(h0+t+.67)); }
    else {
      let a=stops[0], c2=stops[stops.length-1];
      for (let k=0;k<stops.length-1;k++){ if (t>=stops[k][0] && t<=stops[k+1][0]){ a=stops[k]; c2=stops[k+1]; break; } }
      const span=(c2[0]-a[0])||1, f=(t-a[0])/span;
      const h=a[1]+(c2[1]-a[1])*f + hd, s=(a[2]+(c2[2]-a[2])*f)/100, v=(a[3]+(c2[3]-a[3])*f)/100;
      const rgb=hsv(h,s,v); r=rgb[0]; g=rgb[1]; b=rgb[2];
    }
    S.pal[i*3]=r; S.pal[i*3+1]=g; S.pal[i*3+2]=b;
  }
}
const pal=S.pal;
const spectral = P.style==='spectral';

// ---- trajectory scratch ----
const maxIter = Math.round(60 + P.depth*300);   // 60..360
if (!S.tx || S.tx.length < 520){ S.tx=new Float32Array(520); S.ty=new Float32Array(520); }
const tx=S.tx, ty=S.ty;

// ---- drift program (K.t seconds — monotonic, never re-phases) ----
const intn=(K.intensity!=null?K.intensity:.6);
const T=K.t*P.speed;
let rotRate=0.035, zoomAmp=0.06, panAmp=0.05;
if (P.act==='spin'){ rotRate=0.085; zoomAmp=0.04; }
else if (P.act==='zoom'){ rotRate=0.018; zoomAmp=0.17; panAmp=0.03; }
const sec=(K.section|0);
const theta = T*rotRate + Math.sin(T*0.13)*0.10 + sec*0.08;
const ct=Math.cos(theta), stt=Math.sin(theta);
const zoom = 0.9 + zoomAmp*Math.sin(T*0.19) + (K.swell||0)*0.08;
const view = 1.15 * zoom / Math.max(0.2, P.scale);   // half-extent shrinks as scale grows (zoom in)
const halfY = view, halfX = view*cw/ch;
const vcx = -0.5 + Math.sin(T*0.11)*panAmp, vcy = Math.cos(T*0.09)*panAmp*0.6;
const anchorX = P.x, anchorY = P.y;

// ---- rolling decay + running max (pass 1) ----
const decay = 0.85 + P.persist*0.13;
const hist=S.hist, csum=S.csum;
let nMax=0;
for (let i=0;i<N4;i++){ const v=hist[i]*decay; hist[i]=v; csum[i]*=decay; if(v>nMax)nMax=v; }

// ---- fire random c-samples; iterate z=z^2+c; plot ESCAPING trajectories (+ mirror) ----
const samples = Math.min(900, Math.floor((150 + P.density*430)*(0.7+intn*0.5) + A.bass*180));
const cx0=-2.05, cx1=0.62, cy1=1.16;   // sample the upper half; mirror-plot the conjugate
const plotCap = 46000; let plotted=0;
function splat(px,py,cc){
  const dx=px-vcx, dy=py-vcy;
  const rx=dx*ct+dy*stt, ry=-dx*stt+dy*ct;     // rotate the view window
  let u=rx/(2*halfX)+0.5, vv=ry/(2*halfY)+0.5;
  u=(u-0.5)+anchorX; vv=(vv-0.5)+anchorY;
  const ix=(u*cw)|0, iy=(vv*ch)|0;
  if (ix>=0&&ix<cw&&iy>=0&&iy<ch){ const bi=iy*cw+ix; const nv=hist[bi]+1; hist[bi]=nv; csum[bi]+=cc; if(nv>nMax)nMax=nv; }
}
for (let s=0; s<samples && plotted<plotCap; s++){
  const cx = cx0 + rnd()*(cx1-cx0);
  const cy = rnd()*cy1;
  const xq=cx-0.25, q=xq*xq+cy*cy;
  if (q*(q+xq) < 0.25*cy*cy) continue;          // inside main cardioid → skip
  if ((cx+1)*(cx+1)+cy*cy < 0.0625) continue;   // inside period-2 bulb → skip
  let zx=0, zy=0, it=0, esc=false;
  for (; it<maxIter; it++){
    tx[it]=zx; ty[it]=zy;
    const zx2=zx*zx, zy2=zy*zy;
    if (zx2+zy2 > 4){ esc=true; break; }
    zy = 2*zx*zy + cy;
    zx = zx2 - zy2 + cx;
  }
  if (!esc || it<3) continue;                   // bounded (inside set) or trivial → skip
  const cc = it/maxIter;                        // escape-count colour coordinate
  for (let k=0;k<it;k++){
    splat(tx[k], ty[k], cc);
    splat(tx[k], -ty[k], cc);                   // conjugate mirror → symmetric buddha
    plotted+=2;
  }
}
S.plotted=plotted;

// ---- log-density + gamma tone map → coarse buffer (pass 2) ----
const expo = 0.42 + P.energy*2.0 + K.intensity*0.4 + K.pulse*0.18 + A.rms*1.0;
const invG = 1/Math.max(0.4, P.gamma);
const logMax = Math.log(1+nMax*expo)+1e-3;
const bg0 = spectral? [4,3,14] : (P.style==='ember'? [11,4,3] : P.style==='ghost'? [7,4,12] : P.style==='bone'? [5,5,8] : [3,4,16]);
const buf=S.buf; buf.loadPixels(); const q2=buf.pixels;
for (let i=0;i<N4;i++){
  const gx=i%cw, gy=(i/cw)|0;
  const amb = 0.5 + 0.5*Math.sin(gx*0.06 + T*0.2)*Math.cos(gy*0.07 - T*0.15);  // faint drifting nebula floor
  const ar=bg0[0]+amb*4, ag=bg0[1]+amb*5, ab=bg0[2]+amb*10;
  const n=hist[i];
  let litR=0, litG=0, litB=0;
  if (n>=1e-3){
    let br=Math.log(1+n*expo)/logMax; if(br>1)br=1; br=Math.pow(br,invG);
    let k;
    if (spectral){ k=((csum[i]/n)*255)|0; if(k<0)k=0; if(k>255)k=255; litR=pal[k*3]*255*br; litG=pal[k*3+1]*255*br; litB=pal[k*3+2]*255*br; }
    else { k=(br*255)|0; if(k>255)k=255; if(k<0)k=0; litR=pal[k*3]*255; litG=pal[k*3+1]*255; litB=pal[k*3+2]*255; }
  }
  let R=ar+litR, G=ag+litG, B=ab+litB;
  const p4=i*4; q2[p4]=R>255?255:R; q2[p4+1]=G>255?255:G; q2[p4+2]=B>255?255:B; q2[p4+3]=255;
}
buf.updatePixels();

// ---- upscale full-frame (soft bloom) + optional gentle ADD glow ----
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(buf,0,0,width,height);
if (!spectral && P.style!=='bone'){
  blendMode(ADD); tint(255, 10+P.energy*12); image(buf,0,0,width,height); noTint(); blendMode(BLEND);
}
